content:
:root {
  --color-primary: #3b82f6;
  --color-primary-hover: #2563eb;
  --color-primary-light: #eff6ff;
  --color-bg: #f8fafc;
  --color-surface: #ffffff;
  --color-border: #e2e8f0;
  --color-text-main: #0f172a;
  --color-text-muted: #64748b;
  --color-success: #10b981;
  --color-success-bg: #ecfdf5;
  --color-warning: #f59e0b;
  --color-warning-bg: #fffbeb;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.07), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-sans);
  background-color: var(--color-bg);
  color: var(--color-text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 32px 20px 48px;
}

.header {
  margin-bottom: 28px;
}

.header-title {
  font-size: 28px;
  font-weight: 700;
  color: var(--color-text-main);
  letter-spacing: -0.02em;
}

.header-subtitle {
  font-size: 14px;
  color: var(--color-text-muted);
  margin-top: 6px;
}

.toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 24px;
  padding: 16px 20px;
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
}

.preset-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  font-weight: 600;
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.15s ease-in-out;
  border: 1px solid transparent;
  outline: none;
}

.btn:focus-visible {
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.35);
}

.btn-primary {
  background-color: var(--color-primary);
  color: #ffffff;
}

.btn-primary:hover {
  background-color: var(--color-primary-hover);
}

.btn-outline {
  background-color: #ffffff;
  color: var(--color-text-muted);
  border-color: var(--color-border);
}

.btn-outline:hover {
  background-color: #f1f5f9;
  color: var(--color-text-main);
}

.btn-active {
  box-shadow: 0 2px 4px rgba(59, 130, 246, 0.25);
}

.toggle-container {
  display: flex;
  align-items: center;
}

.toggle-label {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 500;
  color: var(--color-text-main);
  cursor: pointer;
  user-select: none;
}

.toggle-checkbox {
  width: 16px;
  height: 16px;
  accent-color: var(--color-primary);
  cursor: pointer;
}

.summary-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-bottom: 28px;
}

.summary-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 20px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  transition: border-color 0.15s, background-color 0.15s;
}

.summary-card.is-achieved {
  border-color: var(--color-success);
  background-color: #f0fdf4;
}

.summary-card.is-achieved .summary-value {
  color: #15803d;
}

.summary-label {
  font-size: 13px;
  font-weight: 600;
  color: var(--color-text-muted);
  margin-bottom: 8px;
}

.summary-value {
  font-size: 24px;
  font-weight: 700;
  color: var(--color-text-main);
  margin-bottom: 6px;
  letter-spacing: -0.01em;
}

.summary-subtext {
  font-size: 12px;
  color: var(--color-text-muted);
}

.dashboard-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

.card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 24px;
  box-shadow: var(--shadow-sm);
}

.card-title {
  font-size: 18px;
  font-weight: 700;
  color: var(--color-text-main);
  margin-bottom: 20px;
}

.chart-container {
  width: 100%;
  min-height: 360px;
}

.chart-container.chart-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: #f8fafc;
  border-radius: var(--radius-sm);
  border: 1px dashed var(--color-border);
}

.empty-message {
  font-size: 14px;
  color: var(--color-text-muted);
}

.chart-tooltip {
  background-color: #ffffff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  padding: 8px 12px;
  box-shadow: var(--shadow-md);
}

.chart-tooltip-label {
  font-size: 13px;
  font-weight: 600;
  color: var(--color-text-main);
  margin-bottom: 4px;
}

.chart-tooltip-item {
  font-size: 12px;
  font-weight: 500;
  line-height: 1.5;
}

.table-container {
  width: 100%;
  overflow-x: auto;
}

.sales-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 14px;
}

.table-header {
  background-color: #f8fafc;
  border-bottom: 2px solid var(--color-border);
}

.table-cell {
  padding: 12px 16px;
  vertical-align: middle;
}

.table-header .table-cell {
  font-size: 13px;
  font-weight: 600;
  color: var(--color-text-muted);
  white-space: nowrap;
}

.table-row {
  border-bottom: 1px solid var(--color-border);
  transition: background-color 0.15s ease-in-out;
}

.table-row:hover {
  background-color: #f8fafc;
}

.table-row.is-achieved {
  background-color: #f0fdf4;
}

.table-row.is-achieved:hover {
  background-color: #dcfce7;
}

.input-sales {
  width: 120px;
  padding: 6px 10px;
  font-size: 14px;
  color: var(--color-text-main);
  background-color: #ffffff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}

.input-sales:focus {
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.2);
}

.badge {
  display: inline-block;
  padding: 4px 10px;
  border-radius: 9999px;
  font-size: 12px;
  font-weight: 600;
  line-height: 1.2;
}

.badge-success {
  background-color: var(--color-success-bg);
  color: var(--color-success);
}

.badge-warning {
  background-color: var(--color-warning-bg);
  color: var(--color-warning);
}

@media (max-width: 992px) {
  .summary-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 640px) {
  .app-container {
    padding: 20px 14px;
  }

  .summary-grid {
    grid-template-columns: 1fr;
  }

  .toolbar {
    flex-direction: column;
    align-items: flex-start;
  }

  .preset-buttons {
    width: 100%;
  }

  .preset-buttons .btn {
    flex: 1 1 calc(50% - 8px);
  }

  .header-title {
    font-size: 22px;
  }

  .card {
    padding: 16px;
  }
}

export type PresetKey = '2024' | '2023' | 'targetOnly';

export type MonthName =
  | '1月'
  | '2月'
  | '3月'
  | '4月'
  | '5月'
  | '6月'
  | '7月'
  | '8月'
  | '9月'
  | '10月'
  | '11月'
  | '12月';

export interface MonthlySalesRecord {
  month: MonthName;
  sales: number;
  target: number;
}

export interface SalesSummaryData {
  totalSales: number;
  totalTarget: number;
  averageSales: number;
  maxMonth: string;
  maxSales: number;
  minMonth: string;
  minSales: number;
  achievementRate: number;
}

export interface SalesChartProps {
  data: MonthlySalesRecord[];
  showTarget: boolean;
}

export interface SalesSummaryProps {
  summary: SalesSummaryData;
}

export interface SalesTableProps {
  data: MonthlySalesRecord[];
  onUpdateSales: (monthIndex: number, newSales: number) => void;
  onUpdateTarget: (monthIndex: number, newTarget: number) => void;
}

import { SalesSummaryProps } from '../types';

const formatYen = (val: number): string => {
  return `${val.toLocaleString()} 万円`;
};

export default function SalesSummary({ summary }: SalesSummaryProps) {
  const isAchieved = summary.achievementRate >= 100;

  return (
    <div className="summary-grid">
      <div className="summary-card">
        <div className="summary-label">年間総売上</div>
        <div className="summary-value" aria-label={`年間総売上: ${formatYen(summary.totalSales)}`}>
          {formatYen(summary.totalSales)}
        </div>
        <div className="summary-subtext">全12ヶ月の合計実績</div>
      </div>

      <div className="summary-card">
        <div className="summary-label">月平均売上</div>
        <div className="summary-value" aria-label={`月平均売上: ${formatYen(summary.averageSales)}`}>
          {formatYen(summary.averageSales)}
        </div>
        <div className="summary-subtext">1ヶ月あたりの平均実績</div>
      </div>

      <div className="summary-card">
        <div className="summary-label">最高売上月</div>
        <div
          className="summary-value"
          aria-label={`最高売上月: ${summary.maxMonth}、${formatYen(summary.maxSales)}`}
        >
          {summary.maxMonth} ({formatYen(summary.maxSales)})
        </div>
        <div className="summary-subtext">最低: {summary.minMonth} ({formatYen(summary.minSales)})</div>
      </div>

      <div className={`summary-card ${isAchieved ? 'is-achieved' : ''}`}>
        <div className="summary-label">年間目標達成率</div>
        <div
          className="summary-value"
          aria-label={`年間目標達成率: ${summary.achievementRate.toFixed(1)}パーセント`}
        >
          {summary.achievementRate.toFixed(1)}%
        </div>
        <div className="summary-subtext">年間合計目標に対する進捗率</div>
      </div>
    </div>
  );
}

import { ResponsiveContainer, BarChart, Bar, CartesianGrid, XAxis, YAxis, Tooltip, Legend } from 'recharts';
import { SalesChartProps } from '../types';

interface TooltipPayloadItem {
  name: string;
  value: number;
  color: string;
}

interface CustomTooltipProps {
  active?: boolean;
  payload?: TooltipPayloadItem[];
  label?: string;
}

const CustomTooltip = ({ active, payload, label }: CustomTooltipProps) => {
  if (active && payload && payload.length) {
    return (
      <div className="chart-tooltip">
        <div className="chart-tooltip-label">{label}</div>
        {payload.map((entry, index) => (
          <div key={`item-${index}`} className="chart-tooltip-item" style={{ color: entry.color }}>
            {entry.name}: {entry.value?.toLocaleString()} 万円
          </div>
        ))}
      </div>
    );
  }
  return null;
};

export default function SalesChart({ data = [], showTarget }: SalesChartProps) {
  if (!data || data.length === 0) {
    return (
      <div className="card">
        <h2 className="card-title">月別売上推移グラフ</h2>
        <div className="chart-container chart-empty">
          <p className="empty-message">データがありません</p>
        </div>
      </div>
    );
  }

  return (
    <div className="card">
      <h2 className="card-title">月別売上推移グラフ</h2>
      <div className="chart-container">
        <ResponsiveContainer width="100%" height={360}>
          <BarChart data={data} margin={{ top: 20, right: 30, left: 20, bottom: 10 }}>
            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
            <XAxis dataKey="month" tick={{ fill: '#64748b', fontSize: 13 }} axisLine={{ stroke: '#cbd5e1' }} />
            <YAxis
              tick={{ fill: '#64748b', fontSize: 13 }}
              axisLine={{ stroke: '#cbd5e1' }}
              tickFormatter={(value: number) => (value === 0 ? '0' : `${value}万円`)}
            />
            <Tooltip content={<CustomTooltip />} />
            <Legend verticalAlign="top" height={36} wrapperStyle={{ paddingBottom: '10px' }} />
            <Bar dataKey="sales" name="売上実績" fill="#3b82f6" radius={[4, 4, 0, 0]} maxBarSize={48} />
            {showTarget && (
              <Bar dataKey="target" name="目標金額" fill="#94a3b8" radius={[4, 4, 0, 0]} maxBarSize={48} />
            )}
          </BarChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}

import { ChangeEvent } from 'react';
import { SalesTableProps } from '../types';

export default function SalesTable({
  data = [],
  onUpdateSales,
  onUpdateTarget
}: SalesTableProps) {
  const handleSalesChange = (index: number, e: ChangeEvent<HTMLInputElement>) => {
    const rawVal = e.target.value;
    if (rawVal === '') {
      onUpdateSales?.(index, 0);
      return;
    }
    const val = Number(rawVal);
    if (!isNaN(val)) {
      onUpdateSales?.(index, Math.max(0, val));
    }
  };

  const handleTargetChange = (index: number, e: ChangeEvent<HTMLInputElement>) => {
    const rawVal = e.target.value;
    if (rawVal === '') {
      onUpdateTarget?.(index, 0);
      return;
    }
    const val = Number(rawVal);
    if (!isNaN(val)) {
      onUpdateTarget?.(index, Math.max(0, val));
    }
  };

  return (
    <div className="card">
      <h2 className="card-title">月別データ編集</h2>
      <div className="table-container">
        <table className="sales-table">
          <thead>
            <tr className="table-header">
              <th className="table-cell">月</th>
              <th className="table-cell">売上実績 (万円)</th>
              <th className="table-cell">目標金額 (万円)</th>
              <th className="table-cell">達成率</th>
              <th className="table-cell">ステータス</th>
            </tr>
          </thead>
          <tbody>
            {data.map((record, index) => {
              const rate = record.target > 0 ? (record.sales / record.target) * 100 : 0;
              const isAchieved = record.sales >= record.target;

              return (
                <tr
                  key={record.month}
                  className={`table-row ${isAchieved ? 'is-achieved' : ''}`}
                >
                  <td className="table-cell" style={{ fontWeight: 600 }}>{record.month}</td>
                  <td className="table-cell">
                    <input
                      type="number"
                      className="input-sales"
                      value={record.sales}
                      min={0}
                      step={10}
                      aria-label={`${record.month}の売上実績`}
                      onChange={(e) => handleSalesChange(index, e)}
                    />
                  </td>
                  <td className="table-cell">
                    <input
                      type="number"
                      className="input-sales"
                      value={record.target}
                      min={0}
                      step={10}
                      aria-label={`${record.month}の目標金額`}
                      onChange={(e) => handleTargetChange(index, e)}
                    />
                  </td>
                  <td className="table-cell">
                    {rate.toFixed(1)}%
                  </td>
                  <td className="table-cell">
                    <span className={`badge ${isAchieved ? 'badge-success' : 'badge-warning'}`}>
                      {isAchieved ? '達成' : '未達'}
                    </span>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import { useState, useMemo } from 'react';
import { MonthlySalesRecord, SalesSummaryData, PresetKey } from './types';
import SalesSummary from './components/SalesSummary';
import SalesChart from './components/SalesChart';
import SalesTable from './components/SalesTable';

const MONTH_NAMES = [
  '1月', '2月', '3月', '4月', '5月', '6月',
  '7月', '8月', '9月', '10月', '11月', '12月'
] as const;

const PRESETS: Record<PresetKey, MonthlySalesRecord[]> = {
  '2024': [
    { month: '1月', sales: 420, target: 400 },
    { month: '2月', sales: 380, target: 400 },
    { month: '3月', sales: 550, target: 500 },
    { month: '4月', sales: 490, target: 450 },
    { month: '5月', sales: 460, target: 450 },
    { month: '6月', sales: 520, target: 480 },
    { month: '7月', sales: 610, target: 550 },
    { month: '8月', sales: 580, target: 520 },
    { month: '9月', sales: 530, target: 500 },
    { month: '10月', sales: 590, target: 520 },
    { month: '11月', sales: 640, target: 580 },
    { month: '12月', sales: 720, target: 650 }
  ],
  '2023': [
    { month: '1月', sales: 350, target: 380 },
    { month: '2月', sales: 330, target: 360 },
    { month: '3月', sales: 480, target: 450 },
    { month: '4月', sales: 410, target: 400 },
    { month: '5月', sales: 430, target: 420 },
    { month: '6月', sales: 460, target: 450 },
    { month: '7月', sales: 510, target: 500 },
    { month: '8月', sales: 490, target: 480 },
    { month: '9月', sales: 470, target: 460 },
    { month: '10月', sales: 520, target: 500 },
    { month: '11月', sales: 560, target: 520 },
    { month: '12月', sales: 630, target: 600 }
  ],
  'targetOnly': MONTH_NAMES.map((month) => ({
    month,
    sales: 0,
    target: 500
  }))
};

export default function App() {
  const [selectedPreset, setSelectedPreset] = useState<PresetKey>('2024');
  const [salesData, setSalesData] = useState<MonthlySalesRecord[]>(PRESETS['2024']);
  const [showTarget, setShowTarget] = useState<boolean>(true);

  const handlePresetChange = (presetKey: PresetKey) => {
    setSelectedPreset(presetKey);
    setSalesData(PRESETS[presetKey].map((item) => ({ ...item })));
  };

  const handleReset = () => {
    setSalesData(PRESETS[selectedPreset].map((item) => ({ ...item })));
  };

  const handleUpdateRecord = (
    monthIndex: number,
    field: 'sales' | 'target',
    value: number
  ) => {
    setSalesData((prev) => {
      const next = [...prev];
      if (next[monthIndex]) {
        next[monthIndex] = { ...next[monthIndex], [field]: value };
      }
      return next;
    });
  };

  const summary = useMemo<SalesSummaryData>(() => {
    if (salesData.length === 0) {
      return {
        totalSales: 0,
        totalTarget: 0,
        averageSales: 0,
        maxMonth: '-',
        maxSales: 0,
        minMonth: '-',
        minSales: 0,
        achievementRate: 0
      };
    }

    let totalSales = 0;
    let totalTarget = 0;
    let maxRecord = salesData[0];
    let minRecord = salesData[0];
    const hasAnySales = salesData.some((item) => item.sales > 0);

    salesData.forEach((item) => {
      totalSales += item.sales;
      totalTarget += item.target;
      if (item.sales > maxRecord.sales) {
        maxRecord = item;
      }
      if (item.sales < minRecord.sales) {
        minRecord = item;
      }
    });

    const averageSales = Math.round(totalSales / salesData.length);
    const achievementRate = totalTarget > 0 ? (totalSales / totalTarget) * 100 : 0;

    return {
      totalSales,
      totalTarget,
      averageSales,
      maxMonth: hasAnySales ? maxRecord.month : '-',
      maxSales: hasAnySales ? maxRecord.sales : 0,
      minMonth: hasAnySales ? minRecord.month : '-',
      minSales: hasAnySales ? minRecord.sales : 0,
      achievementRate
    };
  }, [salesData]);

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="header-title">年間売上ダッシュボード</h1>
        <p className="header-subtitle">1月から12月までの売上実績・目標比較およびシミュレーション</p>
      </header>

      <div className="toolbar">
        <div className="preset-buttons">
          <button
            type="button"
            className={`btn ${selectedPreset === '2024' ? 'btn-primary btn-active' : 'btn-outline'}`}
            onClick={() => handlePresetChange('2024')}
          >
            2024年度実績
          </button>
          <button
            type="button"
            className={`btn ${selectedPreset === '2023' ? 'btn-primary btn-active' : 'btn-outline'}`}
            onClick={() => handlePresetChange('2023')}
          >
            2023年度実績
          </button>
          <button
            type="button"
            className={`btn ${selectedPreset === 'targetOnly' ? 'btn-primary btn-active' : 'btn-outline'}`}
            onClick={() => handlePresetChange('targetOnly')}
          >
            目標計画値
          </button>
          <button
            type="button"
            className="btn btn-outline"
            onClick={handleReset}
          >
            初期値に戻す
          </button>
        </div>

        <div className="toggle-container">
          <label className="toggle-label">
            <input
              type="checkbox"
              className="toggle-checkbox"
              checked={showTarget}
              onChange={(e) => setShowTarget(e.target.checked)}
            />
            目標値をグラフに表示
          </label>
        </div>
      </div>

      <SalesSummary summary={summary} />

      <div className="dashboard-grid">
        <SalesChart data={salesData} showTarget={showTarget} />
        <SalesTable
          data={salesData}
          onUpdateSales={(monthIndex, newSales) => handleUpdateRecord(monthIndex, 'sales', newSales)}
          onUpdateTarget={(monthIndex, newTarget) => handleUpdateRecord(monthIndex, 'target', newTarget)}
        />
      </div>
    </div>
  );
}
